import pytest

from bedrock_protocol import v975, v1001, v2168, v2225

VERSIONS = [v975, v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at de090ae:
# packet.SubClientLogin{ConnectionRequest: []byte("sub-client-jwt")}
SUB_CLIENT_JWT = bytes.fromhex("0e7375622d636c69656e742d6a7774")

# generated by gophertunnel b8bd735:
# packet.SubClientLogin{ConnectionRequest: []byte{}}
EMPTY = bytes.fromhex("00")

GOLDENS = [
    *[
        pytest.param(
            version.SubClientLoginPacket(connection_request="sub-client-jwt"),
            SUB_CLIENT_JWT,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-request",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.SubClientLoginPacket(connection_request=""),
            EMPTY,
            id=f"{version.__name__.removeprefix('bedrock_protocol.')}-empty-request",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_sub_client_login_is_packet_94(version):
    assert version.PACKETS[94] is version.SubClientLoginPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_client_login_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_client_login_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
